func CatchError[T any](res *Result[T], catcher func(error) T, when ...error) {
	defer func() {
		if res.IsOk() {
			return
		}

		err := res.MustUnwrapErr()
		if when == nil {
			*res = Result[T]{value: catcher(err)}
			return
		}
		for _, target := range when {
			if !errors.Is(err, target) {
				continue
			}
			*res = Result[T]{value: catcher(err)}
			break
		}
	}()
	defer Recover(res)
	if r := recover(); r != nil {
		panic(r)
	}
}
package result

// Failable is a result that can be used to check if an error occurred
// and does not hold any value
type Failable struct {
	err error
}

func NewFailable(err error) Failable {
	return Failable{err}
}

func (f Failable) IsOk() bool {
	return f.err == nil
}

func (f Failable) IsErr() bool {
	return f.err != nil
}

func (f Failable) Err() error {
	return f.err
}

func (f Failable) UnwrapErr() error {
	return f.err
}

// Must unraps the result and panics if there is an error
// can be caughts with a defer result.Recover(&err)
func (f Failable) Must() {
	if f.err != nil {
		panic(resultError{f.err})
	}
}
package promise

type AsyncResult[T any] struct {
	Value T
	Error error
}

type Promise[T any] struct {
	ch chan AsyncResult[T]
}

func New[T any](fn func() (T, error)) *Promise[T] {
	ch := make(chan AsyncResult[T])
	go func() {
		defer close(ch)
		v, err := fn()
		ch <- AsyncResult[T]{Value: v, Error: err}
	}()
	return &Promise[T]{ch: ch}
}

func (p *Promise[T]) Await() (T, error) {
	result := <-p.ch
	return result.Value, result.Error
}

